 * Small helpers for recognizing the tokens the limiter file's grammar is
 * built from: names / prefixes / keys, and unsigned decimal integers.
 */

const NAME_RE = /^[A-Za-z0-9_./:-]+$/

export function isName(text) {
  return NAME_RE.test(text)
}

const INT_RE = /^(0|[1-9][0-9]*)$/

/**
 * Parses an unsigned decimal integer with no sign and no superfluous
 * leading zero. Returns a BigInt, or null when the text is not a
 * well-formed integer at all.
 */
export function parseUint(text) {
  if (!INT_RE.test(text)) return null
  return BigInt(text)
}
"}

