{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-GmCRqW/src/policy.js","content":"/**
 * The two kinds of policy, each holding one independent state per key.
 * All arithmetic is done with BigInt so refills stay exact fractions and
 * ticks/counts are never limited by double precision.
 */

export class TokenBucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    // key -> { numerator, lastTick } where tokens held = numerator / per
    this.states = new Map()
  }

  #stateFor(key, tick) {
    let state = this.states.get(key)
    if (!state) {
      state = { numerator: this.capacity * this.per, lastTick: tick }
      this.states.set(key, state)
    }
    return state
  }

  /** Advances this policy's state for `key` to `tick`. */
  advance(key, tick) {
    const state = this.#stateFor(key, tick)
    const delta = tick - state.lastTick
    if (delta > 0n) {
      const cap = this.capacity * this.per
      let numerator = state.numerator + this.refill * delta
      if (numerator > cap) numerator = cap
      state.numerator = numerator
      state.lastTick = tick
    }
    return state
  }

  /** Whether `key` currently holds at least one whole token. */
  allows(key) {
    const state = this.states.get(key)
    return state.numerator >= this.per
  }

  /** Spends exactly one token for `key`. */
  record(key) {
    const state = this.states.get(key)
    state.numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    // key -> array of remembered ticks, oldest first
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (!state) {
      state = []
      this.states.set(key, state)
    }
    return state
  }

  /** Advances this policy's state for `key` to `tick`, forgetting stale ticks. */
  advance(key, tick) {
    const state = this.#stateFor(key)
    const threshold = tick - this.span
    let cut = 0
    while (cut < state.length && state[cut] <= threshold) cut += 1
    if (cut > 0) state.splice(0, cut)
    return state
  }

  /** Whether `key` currently has room for one more request. */
  allows(key) {
    const state = this.states.get(key)
    return BigInt(state.length) < this.limit
  }

  /** Remembers one request for `key` at `tick`. */
  record(key, tick) {
    const state = this.states.get(key)
    state.push(tick)
  }
}
"}

