{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-GmCRqW/src/parse.js","content":"import { LineError } from './errors.js'
import { isName, parseUint } from './tokens.js'
import { TokenBucket, SlidingWindow } from './policy.js'

function splitFields(line) {
  return line.split(/\s+/).filter((t) => t.length > 0)
}

function requireField(lineNo, field, least, name) {
  const value = parseUint(field)
  if (value === null || value < least) {
    throw new LineError(lineNo, `${name} must be an integer of at least ${least}`)
  }
  return value
}

/**
 * Parses the limiter file text into the policies, routes and events it
 * declares. Throws LineError on the first problem found.
 */
export function parseProgram(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = new Map() // prefix -> { policyNames: string[] }
  const routeList = [] // preserves declaration order for lookup
  const events = []
  let hasEvents = false
  let lastTick = null
  let lastTickText = null

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const fields = splitFields(trimmed)
    const word = fields[0]

    if (word !== 'bucket' && word !== 'window' && word !== 'route' && word !== 'event') {
      throw new LineError(lineNo, `unknown directive ${word}`)
    }

    if (word === 'bucket' && fields.length !== 5) {
