{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e7-attempts-5-t5/cell-GmCRqW/src/simulate.js","content":"/**
 * Runs the parsed events through the routed policies, producing one verdict
 * record per event in log order.
 */
function routeFor(routeList, key) {
  let best = null
  for (const entry of routeList) {
    if (key.startsWith(entry.prefix)) {
      if (best === null || entry.prefix.length > best.prefix.length) best = entry
    }
  }
  return best
}

export function simulate({ policies, routeList, events }) {
  const results = []

  for (const event of events) {
    const { tick, key } = event
    const route = routeFor(routeList, key)
    const policyNames = route ? route.policyNames : []
    const routePolicies = policyNames.map((name) => policies.get(name))

    for (const policy of routePolicies) {
      policy.advance(key, tick)
    }

    let denier = null
    for (let i = 0; i < routePolicies.length; i += 1) {
      if (!routePolicies[i].allows(key)) {
        denier = policyNames[i]
        break
      }
    }

    if (denier === null) {
      for (const policy of routePolicies) {
        policy.record(key, tick)
      }
    }

    results.push({ tick, key, allowed: denier === null, denier })
  }

  return results
}
"}

