 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import fs from 'node:fs'
import { CliError } from './errors.js'
import { parseProgram } from './parse.js'
import { simulate } from './simulate.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function formatReplay(results) {
  let out = ''
  for (const r of results) {
    if (r.allowed) {
      out += `${r.tick} ${r.key} allow\n`
    } else {
      out += `${r.tick} ${r.key} deny ${r.denier}\n`
    }
  }
  return out
}

function formatSummary(results) {
  const byKey = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n
  for (const r of results) {
    let counts = byKey.get(r.key)
    if (!counts) {
      counts = { allowed: 0n, denied: 0n }
      byKey.set(r.key, counts)
    }
    if (r.allowed) {
      counts.allowed += 1n
      totalAllowed += 1n
    } else {
      counts.denied += 1n
      totalDenied += 1n
    }
  }
  const keys = [...byKey.keys()].sort()
  let out = ''
  for (const key of keys) {
    const counts = byKey.get(key)
    out += `${key} allowed=${counts.allowed} denied=${counts.denied}\n`
  }
  out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  return out
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exitCode = 2
    return
  }
  const mode = args[0]

  let text
  try {
    text = readStdin()
  } catch (err) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exitCode = 2
    return
  }

  try {
    const program = parseProgram(text)
    const results = simulate(program)
    const out = mode === 'replay' ? formatReplay(results) : formatSummary(results)
    process.stdout.write(out)
  } catch (err) {
    if (err instanceof CliError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exitCode = 2
      return
    }
    throw err
  }
}

main()
